import React, { useState, useContext } from 'react';
import Alert from 'react-s-alert';
import { observer } from 'mobx-react-lite';
import { usePrevious } from '../../../../../miscellaneous/hooks';
import { Box, Button, COLORS, SPACE } from '../../../../../styles';
import { Input } from '../../../../../components/Input';
import { StoreContext } from '../../../../../store/store.context';
import { feathersApp } from '../../../../../utils/feathers';

const WAIT_MINUTES = 5;

const PhoneNumberCheck: React.FC = () => {
  const store = useContext(StoreContext).chatStore;
  const [canSendSMS, setCanSendSMS] = useState(true);
  const [seconds, setSeconds] = useState(WAIT_MINUTES * 60);
  const prevSeconds = usePrevious(seconds);

  function onClick() {
    if (!store.isPhoneValid()) {
      Alert.error('请输入正确的手机号哦');
      return;
    }

    setCanSendSMS(false);

    return feathersApp
      .service('api/check-phone')
      .create({
        phone: store.phone,
      })
      .then((data: { message: string }) => {
        Alert.success(data.message);
        setTimeout(() => {
          setCanSendSMS(true);
        }, WAIT_MINUTES * 60 * 1000);

        const interval = setInterval(() => {
          if (prevSeconds && prevSeconds - 1 < 0) {
            clearInterval(interval);
            setSeconds(WAIT_MINUTES * 60);
          } else {
            setSeconds(v => v - 1);
          }
        }, 1000);
      })
      .catch((e: { message: string }) => {
        Alert.error(e.message);
        setCanSendSMS(true);
      });
  }

  return (
    <Box alignItems="stretch" width={1}>
      <Box width={[0.6, 0.65]}>
        <Input
          type="text"
          placeholder="请输入短信验证码"
          value={store.validationCode}
          onChange={e => {
            store.update(
              'validationCode',
              // @ts-ignore
              e.currentTarget.value,
            );
          }}
          borderRadius="4px 0 0 4px"
        />
      </Box>
      <Box width={[0.4, 0.35]}>
        <Button
          px={SPACE.xxxSmall}
          width={1}
          borderRadius="0 4px 4px 0"
          minHeight="initial"
          maxHeight="initial"
          onClick={onClick}
          // bg={canSendSMS ? COLORS.primary : COLORS.grey1}
          bg={'#7f8fa6'}
          css={`
            pointer-events: ${canSendSMS ? 'auto' : 'none'};
          `}
        >
          {canSendSMS ? '获取验证码' : `${seconds}秒`}
        </Button>
      </Box>
    </Box>
  );
};

export default observer(PhoneNumberCheck);
